The following holds:
    \begin{equation*}
    m^*(\varepsilon, T)
    \geq m^\dagger (\varepsilon, T)- \begin{cases}
    	\mathcal{O}\left(m^{1/2}\right) & \text{if }p \neq 1\\
    	o\left(m^{\alpha_T\cdot(1-r)}\right) & \text{if }p = 1
    \end{cases} 
    \end{equation*}

Consider $\boldsymbol{y}=\{y_{it}\mid i=1,\cdots,n,\ t=1,\cdots,T\}$ such that $|\mathcal{N}(\boldsymbol{y})|\leq Km$ for some fixed constant $K$. Define the event:
   \begin{equation}
    \mathcal{E}(\boldsymbol{y})=\left\{\left|\sum_{j=1}^q s_{jT} - \pi_{j}(\boldsymbol{y})\right|\leq \Delta_G(m)\right\}	
    \end{equation}
    Then, $\mathbb{P}(\mathcal{E}(\boldsymbol{y}^\dagger))\geq 1-\delta$ and $\mathbb{P}(\mathcal{E}(\boldsymbol{y}^*))\geq 1-\delta$.

Consider an optimal solution $\boldsymbol{y}^{\textsc{L}}$ to Problem~(28). We have:
   \begin{align*}
   	\sum_{j=1}^q\pi_{j}(\boldsymbol{y}^{\textsc{L}})&\geq m-\sum_{\tau=1}^T \sum_{i =1}^n \left(\frac{\varepsilon}{\left(\sum_{s=1}^{\tau-1}\sum_{i=1}^n y^{\textsc{L}}_{is}+1\right)^r}+\right)y^{\textsc{L}}_{i\tau}\cdot d_\star\\
	\sum_{j=1}^q\pi_{j}(\boldsymbol{y}^{\textsc{L}})&\leq m-\sum_{\tau=1}^T\sum_{i=1}^n\left(\frac{\varepsilon}{\left(\sum_{s=1}^{t-1}\sum_{i=1}^n y^{\textsc{L}}_{is}+1\right)^r}\right)y^{\textsc{L}}_{i\tau}
   \end{align*}

For sufficiently large $m$, we have:
    \begin{align*}
        \frac{m}{d_\star} \leq |\mathcal{N}(\boldsymbol{y}^\dagger)|&\leq  d_\star c_0\left(m + \varepsilon\cdot p \cdot \zeta_T\cdot m^{\alpha_T\cdot(1-r)} +\Delta(m)+3\Delta_G(m)\right)\\
        \frac{m(1-\delta)}{d_\star} \leq \mathbb{E}[|\mathcal{N}(\boldsymbol{y}^*)|]&\leq   d_\star c_0\left(m + \varepsilon\cdot p \cdot \zeta_T\cdot m^{\alpha_T\cdot(1-r)} + \Delta(m)\right)      
    \end{align*}

The following holds, as $m,\Delta\to \infty$:
   \begin{align*}
       \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(m)-d_\star c_0\left(\Delta+\mathcal{O}\left(\Delta^{g(r)}\right)\right)\leq\sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(m-\Delta)\leq \sum_{t=1}^T \sum_{i=1}^n y_{it}^\dagger(m)-\frac{c_0\Delta}{d_\star}
   \end{align*}
